DROP PROCEDURE IF EXISTS `CreateAppDB`;;
CREATE PROCEDURE `CreateAppDB`(
IN db_name VARCHAR(50))
BEGIN

SET @s = CONCAT('CREATE DATABASE `', db_name,'`');
PREPARE stmt FROM @s;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;


SET @s = CONCAT('GRANT ALL ON `', db_name, '`.* TO \'www-data\'@localhost');
PREPARE stmt FROM @s;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;


SET @s = CONCAT('GRANT SUPER ON *.* TO \'www-data\'@localhost');
PREPARE stmt FROM @s;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
END;;

